const base = $('Normalize Payload').first().json;
const contexto = $('Fetch Gemini Context').first().json;
const incoming = $input.first()?.json || {};
const geminiAutorizado = contexto.gemini_autorizado === true && typeof contexto.descripcion === 'string' && contexto.descripcion.trim() !== '';
const fotoAutorizada = geminiAutorizado && contexto.foto_autorizada === true;

const sanitizarPII = (texto) => {
  let t = String(texto || '');
  t = t.replace(/\b(?:https?:\/\/|www\.)\S+/gi, '[ENLACE]');
  t = t.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[CORREO]');
  t = t.replace(/(?<!\w)@[A-Za-z0-9_.]{2,}/g, '[USUARIO]');
  t = t.replace(/\b(?:c\.?\s*c\.?|c[eé]dula|t\.?\s*i\.?|c\.?\s*e\.?|nit|rut|pasaporte|documento|identificaci[oó]n|tel[eé]fono|tel\.?|fijo|cel(?:ular)?|whatsapp|wsp|contacto|ext(?:ensi[oó]n)?)\b\s*[:#.-]?\s*\d[\d.\s-]{3,15}\d/gi, '[DATO_CONTACTO]');
  t = t.replace(/(?<!\d)(?:\+?57[\s.-]?)?(?:3\d{2}|60[1-8])[\s.-]?\d{3}[\s.-]?\d{4}(?!\d)/g, '[TELEFONO]');
  t = t.replace(/\b(?:\d{1,3}(?:\.\d{3}){1,3}|\d{6,12})\b/g, '[NUMERO]');
  t = t.replace(/\bplaca\s*[:#-]?\s*[A-Z]{2,3}[\s-]?\d{2,3}[A-Z]?\b/gi, 'placa [PLACA]');
  t = t.replace(/\b(?:[A-Z]{3}-?\d{3}|[A-Z]{3}-?\d{2}[A-Z])\b/g, '[PLACA]');
  t = t.replace(/\b(?:calle|cll?|carrera|cra|kr|avenida|av(?:da)?|diagonal|diag|dg|transversal|transv|tv|circular|circ|autopista|manzana|mz|lote|lt|bloque|blq|interior|int|casa|apto|apartamento|torre|piso|local|oficina|km|kil[oó]metro)\s*#?\s*\d+[a-zA-Z]?(?:\s*(?:#|no\.?|n°|num\.?|-)\s*\d+[a-zA-Z]?(?:\s*-\s*\d+)?)?/gi, '[DIRECCION]');
  t = t.replace(/\b(?:[Bb]arrio|[Ss]ector|[Uu]rbanizaci[oó]n|[Uu]rb\.?|[Cc]onjunto|[Ee]dificio|[Cc]ondominio|[Vv]ereda|[Cc]orregimiento|[Ff]inca)\s+(?:[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+(?:\s+(?:de|del|la|las|los|[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+)){0,3})/g, '[SECTOR]');
  t = t.replace(/\b(me\s+llamo|mi\s+nombre\s+es|soy|nombre(?:\s+completo)?|denunciante|reportado\s+por|se[ñn]or(?:a)?|sr\.?|sra\.?|don|do[ñn]a|vecin[oa]|propietari[oa]|due[ñn][oa]|agresor(?:a)?|atentamente|cordialmente)\s*[:,-]?\s+([A-ZÁÉÍÓÚÑ][a-záéíóúñ]{1,25}(?:\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]{1,25}){0,3})/gi, (m, trig, nom) => /^[A-ZÁÉÍÓÚÑ]/.test(nom) ? `${trig} [PERSONA]` : m);
  return t.replace(/\s+/g, ' ').trim().slice(0, 1500);
};

let visionText = '';
let visionModel = '';
let visionError = false;
if (fotoAutorizada) {
  const parts = incoming.content?.parts ?? incoming.candidates?.[0]?.content?.parts;
  const texto = typeof incoming.content === 'string' ? incoming.content
    : (typeof incoming.text === 'string' ? incoming.text
      : (Array.isArray(parts) ? parts.filter(p => !p?.thought).map(p => p?.text || '').join(' ') : ''));
  visionText = incoming.error ? '' : sanitizarPII(texto);
  visionError = !visionText;
  if (!visionError) visionModel = 'models/gemini-3.5-flash-lite';
}

return [{
  json: {
    ...base,
    geminiAutorizado,
    fotoAutorizada,
    descripcion_ia: geminiAutorizado ? sanitizarPII(contexto.descripcion) : '',
    visionSummary: visionText || (fotoAutorizada ? 'No se pudo analizar la imagen sintetica.' : 'Sin imagen sintetica autorizada.'),
    visionModel,
    visionError
  }
}];

const norm = $('Normalize Payload').first().json;
const visionCtx = $('Prepare Vision Context').first().json;

let iaRaw = {};
let iaError = !visionCtx.geminiAutorizado || visionCtx.visionError;
try {
  iaRaw = $('Analyze Text Triage').first().json || {};
  if (iaRaw.error) iaError = true;
} catch (e) {
  iaError = true;
}

let dupRaw = {};
try {
  dupRaw = $('Detect Duplicates').first().json || {};
} catch (e) {
  dupRaw = {};
}

let cargaRaw = {};
try {
  cargaRaw = $('Fetch Vet Workload').first().json || {};
} catch (e) {
  cargaRaw = {};
}

let parsedIa = {};
const parts = iaRaw.content?.parts ?? iaRaw.candidates?.[0]?.content?.parts;
const candidateText =
  typeof iaRaw.content === 'string'
    ? iaRaw.content
    : (typeof iaRaw.text === 'string'
        ? iaRaw.text
        : (Array.isArray(parts)
            ? parts.filter((p) => !p?.thought).map((p) => p?.text || '').join('')
            : (typeof iaRaw === 'object' && iaRaw.prioridad_sugerida ? JSON.stringify(iaRaw) : '')));

if (!iaError && candidateText) {
  try {
    const cleaned = candidateText.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
    const obj = JSON.parse(cleaned);
    if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
      iaError = true;
    } else {
      parsedIa = obj;
    }
  } catch (e) {
    iaError = true;
  }
} else {
  iaError = true;
}

const PRIORIDADES_PERMITIDAS = new Set(['URGENTE', 'ALTA', 'MEDIA', 'BAJA']);
const ORDEN_PRIORIDAD = { BAJA: 1, MEDIA: 2, ALTA: 3, URGENTE: 4 };
const rawPrio = String(parsedIa.prioridad_sugerida || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim()
  .toUpperCase();
const mapPrioridad = (val) => {
  if (PRIORIDADES_PERMITIDAS.has(val)) return val;
  if (val === 'CRITICA' || val === 'EMERGENCIA' || val === 'INMEDIATA' || val === 'MUY ALTA') return 'URGENTE';
  if (val === 'NORMAL' || val === 'MODERADA') return 'MEDIA';
  if (val === 'LEVE') return 'BAJA';
  return null;
};

const limpiarListaStrings = (arr, maxItems = 15, maxLen = 100) => {
  if (!Array.isArray(arr)) return [];
  const vistos = new Set();
  const res = [];
  for (const item of arr) {
    if (typeof item !== 'string') continue;
    const limpio = item.replace(/\s+/g, ' ').trim().slice(0, maxLen);
    if (!limpio) continue;
    const key = limpio.toLowerCase();
    if (vistos.has(key)) continue;
    vistos.add(key);
    res.push(limpio);
    if (res.length >= maxItems) break;
  }
  return res;
};

const prioridadModelo = !iaError ? mapPrioridad(rawPrio) : null;
let prioridadSugerida = prioridadModelo;
let guardrailAplicado = false;
let notaGuardrail = '';

const normalizarTextoClinico = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const textoClinico = normalizarTextoClinico(`${visionCtx.descripcion_ia || ''} ${visionCtx.visionSummary || ''}`);
const sinNegacionInmediata = (regex) => {
  const m = regex.exec(textoClinico);
  if (!m) return false;
  const previo = textoClinico.slice(Math.max(0, m.index - 18), m.index);
  return !/\b(?:sin|no\s+(?:presenta|tiene|hay|muestra)|niega)\s*$/.test(previo);
};

const regexUrgente = /\b(?:atropell\w*|hemorragia\w*|sangrado\s+activo|desangr\w*|envenen\w*|intoxic\w*|convulsion\w*|no\s+respira|dificultad\s+respiratoria|asfixi\w*|inconsciente\w*|agoniz\w*|fractura\s+expuesta|electrocut\w*|mutila\w*)\b/;
const regexAlta = /\b(?:fractura\w*|herida\w*\s+abierta\w*|desnutricion\s+severa|deshidratacion\s+severa|miasis|quemadura\w*\s+grave\w*|cojera\s+severa)\b/;

if (prioridadSugerida) {
  let pisoClinico = null;
  if (sinNegacionInmediata(regexUrgente)) {
    pisoClinico = 'URGENTE';
  } else if (sinNegacionInmediata(regexAlta)) {
    pisoClinico = 'ALTA';
  }
  if (pisoClinico && ORDEN_PRIORIDAD[prioridadSugerida] < ORDEN_PRIORIDAD[pisoClinico]) {
    prioridadSugerida = pisoClinico;
    guardrailAplicado = true;
    notaGuardrail = ` [Regla de priorizacion administrativa: se mantuvo prioridad ${pisoClinico} por el riesgo descrito en la simulacion, frente a ${prioridadModelo} inicial del modelo.]`;
  }
}

let confianzaValida = null;
if (!iaError && typeof parsedIa.nivel_confianza === 'number' && Number.isFinite(parsedIa.nivel_confianza)) {
  confianzaValida = Math.max(0, Math.min(1, Math.round(parsedIa.nivel_confianza * 10000) / 10000));
}

const tieneFotosReales = visionCtx.fotoAutorizada && !visionCtx.visionError;
const signosReportados = !iaError ? limpiarListaStrings(parsedIa.signos_reportados, 15, 100) : [];
const signosFotografia = (!iaError && tieneFotosReales)
  ? limpiarListaStrings(parsedIa.signos_fotografia, 15, 100)
  : [];

let signosValidados = !iaError ? limpiarListaStrings(parsedIa.signos_detectados, 15, 80) : [];
if (signosValidados.length === 0) {
  signosValidados = limpiarListaStrings([...signosReportados, ...signosFotografia], 15, 80);
}

let advertenciasContradiccion = (!iaError && tieneFotosReales)
  ? limpiarListaStrings(parsedIa.advertencias_contradiccion, 5, 400)
  : [];
const contradiccionFotoDescripcion = Boolean(
  !iaError &&
  tieneFotosReales &&
  (parsedIa.contradiccion_foto_descripcion === true || advertenciasContradiccion.length > 0)
);
if (contradiccionFotoDescripcion && advertenciasContradiccion.length === 0) {
  advertenciasContradiccion = [
    'La evidencia fotografica presenta diferencias relevantes frente a la descripcion reportada por el ciudadano; revise ambas antes de decidir.'
  ];
}
if (!contradiccionFotoDescripcion) {
  advertenciasContradiccion = [];
}
if (contradiccionFotoDescripcion && confianzaValida !== null && confianzaValida > 0.75) {
  confianzaValida = 0.75;
}

const schemaInvalido = !iaError && (!prioridadSugerida || typeof parsedIa.justificacion !== 'string' || !parsedIa.justificacion.trim());
const posiblesDuplicados = Array.isArray(dupRaw.posibles_duplicados) ? dupRaw.posibles_duplicados : [];
const vetRec = cargaRaw.veterinario_recomendado || null;
const cargaLista = Array.isArray(cargaRaw.veterinarios) ? cargaRaw.veterinarios : [];

const estadoAnalisis = (iaError || schemaInvalido || visionCtx.visionError || !prioridadSugerida)
  ? ((dupRaw && !dupRaw.error) || (cargaRaw && !cargaRaw.error) ? 'PARCIAL' : 'FALLIDO')
  : 'COMPLETADO';

const justificacionBase = (typeof parsedIa.justificacion === 'string' && parsedIa.justificacion.trim())
  ? parsedIa.justificacion.trim()
  : (iaError || schemaInvalido ? 'Analisis de IA no disponible o respuesta invalida; se recopilaron duplicados y carga laboral.' : '');

return [{
  json: {
    id_peticion: norm.id_peticion,
    backendBaseUrl: norm.backendBaseUrl,
    clave_idempotencia: norm.clave_idempotencia,
    despacho_token: norm.despacho_token || '',
    estado_analisis: estadoAnalisis,
    prioridad_sugerida: prioridadSugerida,
    nivel_confianza: confianzaValida,
    justificacion: `${justificacionBase}${notaGuardrail}`.trim().slice(0, 3000),
    resumen_texto: typeof parsedIa.resumen_texto === 'string' ? parsedIa.resumen_texto.trim().slice(0, 2000) : '',
    resumen_vision: typeof parsedIa.resumen_vision === 'string' && parsedIa.resumen_vision.trim()
      ? parsedIa.resumen_vision.trim().slice(0, 2000)
      : (visionCtx.visionSummary || '').slice(0, 2000),
    signos_detectados: signosValidados,
    signos_reportados: signosReportados,
    signos_fotografia: signosFotografia,
    contradiccion_foto_descripcion: contradiccionFotoDescripcion,
    advertencias_contradiccion: advertenciasContradiccion,
    posibles_duplicados: posiblesDuplicados,
    veterinario_recomendado_id: vetRec ? vetRec.id_veterinario : null,
    justificacion_recomendacion: String(cargaRaw.justificacion_recomendacion || '').slice(0, 1000),
    carga_veterinarios_snapshot: cargaLista,
    modelo_texto_usado: (iaError || schemaInvalido) ? '' : 'models/gemini-3.5-flash-lite',
    modelo_vision_usado: visionCtx.visionModel || '',
    n8n_execution_id: String($execution.id || ''),
    resultado_raw: {
      gemini_demo: true,
      ia: parsedIa,
      ia_prioridad_modelo: prioridadModelo,
      ia_guardrail_aplicado: guardrailAplicado,
      schema_invalido: schemaInvalido,
      duplicados_meta: dupRaw.parametros || {}
    }
  }
}];
